// Real captured 151-byte pump.fun BondingCurve accounts (proc/cont_wire05.ndjson), hex. Shared by the
// protocol, app and junction offset tests via include!(). Each header: (ndjson line, curve pubkey, slot,
// vsol, vtok, real_sol, real_tok). Extracted by proc/offset_probe37.py and proc/offset_probe38.py.
// FX804_*: curve 14PtCZKp.. = mint 9do6fVUE.. (804a86fe), the two states either side of the Mayhem reset.

#[allow(dead_code)]
fn hex_bytes(h: &str) -> Vec<u8> {
    (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap())
        .collect()
}

